<script lang="ts">
 import { onMount } from 'svelte'; import { request } from './api'; import { PageHeader, RefreshButton } from './ui';
 type Account={id:string;code:string;name:string;type:string;normal_balance:string};type Period={id:string;starts_on:string;ends_on:string;status:string};type Reconciliation={id:string;account_code:string;statement_date:string;statement_balance_cents:number;ledger_balance_cents:number;difference_cents:number};
 let accounts=$state<Account[]>([]),periods=$state<Period[]>([]),reconciliations=$state<Reconciliation[]>([]),code=$state(''),name=$state(''),kind=$state('asset'),normal=$state('debit'),starts=$state(''),ends=$state(''),statement=$state(0),reconcileAccount=$state(''),error=$state(''),saving=$state(false);
 const money=(v:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v/100);
 async function load(){try{const x=await request<{accounts:Account[];periods:Period[];reconciliations:Reconciliation[]}>('/v1/admin/accounting');accounts=x.accounts;periods=x.periods;reconciliations=x.reconciliations;if(!reconcileAccount)reconcileAccount=accounts[0]?.id??'';}catch(e){error=e instanceof Error?e.message:'Akuntansi tidak dapat dimuat.';}}
 async function account(){saving=true;try{await request('/v1/admin/accounting/accounts',{method:'POST',body:JSON.stringify({code,name,account_type:kind,normal_balance:normal})});code='';name='';await load();}finally{saving=false;}}
 async function period(){saving=true;try{await request('/v1/admin/accounting/periods',{method:'POST',body:JSON.stringify({starts_on:starts,ends_on:ends})});starts='';ends='';await load();}finally{saving=false;}}
 async function close(id:string){saving=true;try{await request(`/v1/admin/accounting/periods/${id}/close`,{method:'POST'});await load();}finally{saving=false;}}
 async function reconcile(){saving=true;try{await request('/v1/admin/accounting/reconciliations',{method:'POST',body:JSON.stringify({account_id:reconcileAccount,statement_date:new Date().toISOString().slice(0,10),statement_balance_cents:Number(statement)})});await load();}finally{saving=false;}}
 onMount(load);
</script>
<main class="workspace-page"><PageHeader title="Accounting" description="Chart of accounts, periode tutup buku, dan rekonsiliasi bank tenant." backHref="/admin/dashboard"/>{#if error}<p class="alert">{error}</p>{/if}<div class="grid"><section class="panel"><h2>Akun baru</h2><form novalidate onsubmit={(e)=>{e.preventDefault();void account();}}><div class="twocol"><input bind:value={code} placeholder="Kode" required/><input bind:value={name} placeholder="Nama akun" required/></div><div class="twocol"><select bind:value={kind}><option value="asset">Aset</option><option value="liability">Liabilitas</option><option value="equity">Ekuitas</option><option value="income">Pendapatan</option><option value="expense">Beban</option></select><select bind:value={normal}><option value="debit">Debit</option><option value="credit">Kredit</option></select></div><button disabled={saving}>Simpan akun</button></form></section><section class="panel"><h2>Periode buku</h2><form novalidate onsubmit={(e)=>{e.preventDefault();void period();}}><div class="twocol"><input bind:value={starts} type="date" required/><input bind:value={ends} type="date" required/></div><button disabled={saving}>Buka periode</button></form>{#each periods as item (item.id)}<article><span>{item.starts_on} — {item.ends_on}<small>{item.status}</small></span>{#if item.status==='open'}<button class="quiet" disabled={saving} onclick={()=>close(item.id)}>Tutup</button>{/if}</article>{/each}</section></div><div class="grid"><section class="panel"><h2>Rekonsiliasi</h2><form novalidate onsubmit={(e)=>{e.preventDefault();void reconcile();}}><select bind:value={reconcileAccount}>{#each accounts as item}<option value={item.id}>{item.code} — {item.name}</option>{/each}</select><input bind:value={statement} type="number" placeholder="Saldo rekening (sen)"/><button disabled={saving||!reconcileAccount}>Rekonsiliasi hari ini</button></form></section><section class="panel"><header><h2>Akun aktif</h2><RefreshButton onclick={load} label="Muat ulang"/></header>{#each accounts as item (item.id)}<article><strong>{item.code} · {item.name}</strong><small>{item.type} · normal {item.normal_balance}</small></article>{:else}<p class="muted">Belum ada akun.</p>{/each}</section></div><section class="panel"><h2>Rekonsiliasi terbaru</h2>{#each reconciliations as item (item.id)}<article><span><strong>{item.account_code}</strong><small>{item.statement_date}</small></span><span class:ok={item.difference_cents===0}>{money(item.statement_balance_cents)} / ledger {money(item.ledger_balance_cents)} · selisih {money(item.difference_cents)}</span></article>{:else}<p class="muted">Belum ada rekonsiliasi.</p>{/each}</section></main>
<style>.workspace-page,.grid{display:grid;gap:12px}.grid{grid-template-columns:1fr 1fr}.panel{padding:16px;border-radius:var(--radius)}form{display:grid;gap:8px}.twocol,article{display:grid;grid-template-columns:1fr 1fr;gap:8px}article{border-top:1px solid var(--line);padding:10px 0;align-items:center}small{display:block;color:var(--muted);font-size:12px}.quiet{justify-self:end;background:var(--surface-alt);border:1px solid var(--line);color:var(--text)}.ok{color:var(--success)}.alert{color:var(--danger)}@media(max-width:720px){.grid{grid-template-columns:1fr}}</style>
